import React,{useEffect,useLayoutEffect,useRef,useState} from 'react';
import {Modal} from '../../shared/preferences.tsx';
import {dateToCoordinate,coordinateToDate,validateStoryAxis} from '../../../domain/story-axis.mjs';
import {storyAxisPanelsStyle} from './story-axis-panels-style.mjs';

function useSubmission(busy,close){
 const alive=useRef(true),lock=useRef(false),[pending,setPending]=useState(false),[error,setError]=useState('');
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;};},[]);
 const submit=async action=>{if(busy||lock.current)return;lock.current=true;setPending(true);setError('');try{const ok=await action();if(alive.current&&ok)close();}catch(e){if(alive.current)setError(e?.message||'请核对输入后再试。');}finally{lock.current=false;if(alive.current)setPending(false);}};
 return {disabled:busy||pending,error,setError,submit,close:()=>{if(!busy&&!lock.current)close();}};
}
function Sheet({title,submission,children}){useLayoutEffect(()=>{const previous=document.activeElement;let selection;try{selection=[previous.selectionStart,previous.selectionEnd,previous.selectionDirection];}catch{}return()=>{if(!previous?.isConnected)return;previous.focus({preventScroll:true});if(selection&&typeof selection[0]==='number')try{previous.setSelectionRange(...selection);}catch{}};},[]);return <Modal title={title} close={submission.close} className="story-axis-sheet"><style>{storyAxisPanelsStyle}</style>{children}{submission.error&&<p className="sap-error" role="alert">{submission.error}</p>}</Modal>;}
function Footer({submission,label='保存',submitDisabled=false}){return <div className="sap-footer"><button type="button" disabled={submission.disabled} onClick={submission.close}>取消</button><button className="u-primary" type="submit" disabled={submission.disabled||submitDisabled}>{submission.disabled?'保存中…':label}</button></div>;}
function DateFields({value,onChange,calendar,legend='明确日期'}){const gregorian=calendar?.kind==='gregorian',bce=gregorian&&value.year!==''&&value.year<=0;return <fieldset className="sap-date"><legend>{legend}</legend>{gregorian&&<label className="sap-era">纪元<select aria-label={`${legend}纪元`} value={bce?'bce':'ce'} onChange={e=>onChange({...value,year:e.target.value==='bce'?1-Math.max(1,Number(value.year)||1):Math.max(1,1-Number(value.year))})}><option value="ce">公元</option><option value="bce">公元前</option></select></label>}{[['year','年'],['month','月'],['day','日']].map(([key,label])=><label key={key}>{label}<input required aria-label={`${legend}${label}`} inputMode="numeric" type="number" step="1" min={key==='year'&&!gregorian?undefined:1} value={key==='year'&&bce?1-value.year:value[key]} onChange={e=>onChange({...value,[key]:e.target.value===''?'':key==='year'&&bce?1-Number(e.target.value):Number(e.target.value)})}/></label>)}</fieldset>;}

const defaultAxis=()=>({schemaVersion:1,calendar:{kind:'gregorian',name:'公历',era:'公元',visibility:{year:true,month:true,day:true}},anchor:{date:{year:1,month:1,day:1},label:'第一章 · 故事起点'},coordinateUnit:'day',primaryTick:{unit:'year',step:1},legacyMode:'unmapped',tracks:[{id:'story-main',name:'线上',color:'#7c8d73',side:'above'},{id:'story-under',name:'线下',color:'#a38abc',side:'below'}],markers:[]});
export function StoryAxisSetup({axis,chapters=[],busy=false,onSave,close}){
 const [draft,setDraft]=useState(()=>structuredClone(axis||defaultAxis())),[months,setMonths]=useState(()=>(axis?.calendar?.monthLengths||Array(12).fill(30)).join(', ')),[confirmed,setConfirmed]=useState(false),submission=useSubmission(busy,close);
 const calendar=draft.calendar,change=(key,value)=>{setConfirmed(false);setDraft(v=>({...v,[key]:value}));},calendarChange=(key,value)=>change('calendar',{...calendar,[key]:value});
 const submit=e=>{e.preventDefault();void submission.submit(async()=>{if(!confirmed)throw new Error('请先确认故事起点、历法、坐标单位与主刻度。');const next=structuredClone(draft);if(next.calendar.kind==='custom'){if(!months.trim()||months.split(/[,，\s]+/).some(n=>!/^\d+$/.test(n)))throw new Error('每月天数请用逗号分隔的正整数填写。');next.calendar.monthLengths=months.trim().split(/[,，\s]+/).map(Number);}else delete next.calendar.monthLengths;next.anchor.coordinate=dateToCoordinate(next.anchor.date,next.calendar);if(chapters[0])next.anchor.chapterId=chapters[0].id;const result=validateStoryAxis(next);if(result===false)throw new Error('请完整填写有效的时间坐标。');return onSave(next);});};
 return <Sheet title={axis?'故事时间设置':'让故事拥有自己的时间'} submission={submission}><form className="sap-form" onSubmit={submit}><p className="sap-intro">从第一章读者所在的时刻出发。这里的位置独立保存，不改变叙述顺序、大纲或画布。</p><section className="sap-section"><h3><span>01</span> 第一章，读者在哪儿？</h3><label>起点名称<input required maxLength={120} value={draft.anchor.label} onChange={e=>change('anchor',{...draft.anchor,label:e.target.value})}/></label>{chapters.length>0&&<p className="sap-note">第一章：{chapters[0].title} · 锚点只是故事时间参照，不会改动正文。</p>}<DateFields calendar={calendar} legend="起点的故事日期" value={draft.anchor.date} onChange={date=>change('anchor',{...draft.anchor,date,...(chapters[0]?{chapterId:chapters[0].id}:{})})}/></section><section className="sap-section"><h3><span>02</span> 用哪一种历法？</h3><div className="sap-options" role="group" aria-label="历法">{[['gregorian','公历'],['custom','自定义历法']].map(([kind,label])=><button type="button" key={kind} aria-pressed={calendar.kind===kind} onClick={()=>change('calendar',{...calendar,kind,name:kind==='gregorian'?'公历':'故事历',era:kind==='gregorian'?'公元':'故事历'})}>{label}</button>)}</div><div className="sap-grid"><label>历法名称<input required maxLength={60} value={calendar.name||''} onChange={e=>calendarChange('name',e.target.value)}/></label><label>纪年／历的称呼<input maxLength={60} placeholder="如：公元、星历、第三纪元" value={calendar.era||''} onChange={e=>calendarChange('era',e.target.value)}/></label></div>{calendar.kind==='custom'&&<><label>一年中每个月的天数<input required value={months} onChange={e=>{setMonths(e.target.value);setConfirmed(false);}} placeholder="30, 30, 30, 30" inputMode="text"/></label><p className="sap-note">按顺序填写各月天数。自定义历每年重复同一组月份，不含未定义的闰月或闰年；日期由实际天数换算，不从文字名称猜测。</p></>}<fieldset className="sap-display"><legend>日期显示</legend>{[['year','年'],['month','月'],['day','日']].map(([key,label])=><label key={key}><input type="checkbox" checked={calendar.visibility?.[key]!==false} onChange={e=>calendarChange('visibility',{...calendar.visibility,[key]:e.target.checked})}/>{label}</label>)}</fieldset></section><section className="sap-section"><h3><span>03</span> 坐标与醒目的刻度</h3><div className="sap-grid"><label>坐标单位 · 主刻度<select value={draft.primaryTick.unit} onChange={e=>change('primaryTick',{...draft.primaryTick,unit:e.target.value})}><option value="year">年</option><option value="month">月</option><option value="day">日</option></select></label><p className="sap-note">精细位置始终支持每一天，不随显示单位改变。</p></div><label>主刻度间隔<input required type="number" min="1" step="1" value={draft.primaryTick.step} onChange={e=>change('primaryTick',{...draft.primaryTick,step:e.target.value===''?'':Number(e.target.value)})}/></label><p className="sap-note">主刻度只影响显示。即使每年一格，也能安排相邻两天的事件，放大后细看；空白年代会自动折叠。</p></section><label className="sap-confirm"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/><span>已确认故事起点、历法、坐标单位与主刻度</span></label><Footer submission={submission} submitDisabled={!confirmed} label={axis?'保存设置':'开启故事时间线'}/></form></Sheet>;
}
function PositionFields({axis,coordinate,onChange,label='明确位置'}){
 const [mode,setMode]=useState('date');let date;try{date=coordinateToDate(Number(coordinate),axis.calendar);}catch{date={year:1,month:1,day:1};}
 const [dateDraft,setDateDraft]=useState(date),[dateError,setDateError]=useState('');
 useEffect(()=>{if(coordinate==='')return;try{setDateDraft(coordinateToDate(Number(coordinate),axis.calendar));}catch{}},[coordinate]);
 return <div className="sap-position"><div className="sap-position-head"><strong>{label}</strong><button type="button" onClick={()=>setMode(mode==='date'?'coordinate':'date')}>{mode==='date'?'用坐标填写':'用日期填写'}</button></div>{mode==='coordinate'?<label>绝对日坐标<input required type="number" step="1" value={coordinate} onChange={e=>onChange(e.target.value===''?'':Number(e.target.value))}/><small>第一章锚点：{axis.anchor.coordinate}；正负数字均可，与标签文字无关。</small></label>:<DateFields calendar={axis.calendar} value={dateDraft} onChange={next=>{setDateDraft(next);try{const n=dateToCoordinate(next,axis.calendar);setDateError('');onChange(n);}catch(e){setDateError(e.message);onChange('');}}}/>} {dateError&&<small role="alert" className="sap-error">{dateError}</small>}</div>;
}
export function StoryMarkerEditor({marker,coordinate,axis,busy=false,onSave,onDelete,onInsert,close}){
 const [label,setLabel]=useState(marker?.label||''),[point,setPoint]=useState(marker?.coordinate??coordinate??axis.anchor.coordinate),submission=useSubmission(busy,close);
 return <Sheet title={marker?'编辑时间标记':'留一个时间标记'} submission={submission}><form className="sap-form" onSubmit={e=>{e.preventDefault();void submission.submit(()=>{if(point===''||!Number.isSafeInteger(Number(point)))throw new Error('请选择明确的日期或整数日坐标。');return onSave({label:label.trim(),coordinate:Number(point)});});}}><p className="sap-intro">可以叫“某个春天”，也可以叫“鸽子衔枝之年”。名称自由，位置由你明确指定。</p><label>标记名称<input required autoFocus maxLength={160} placeholder="某个春天" value={label} onChange={e=>setLabel(e.target.value)}/></label><PositionFields axis={axis} coordinate={point} onChange={setPoint}/>{marker&&onInsert&&<div className="sap-options"><button type="button" disabled={submission.disabled} onClick={()=>onInsert(marker,'before')}>在此之前插入</button><button type="button" disabled={submission.disabled} onClick={()=>onInsert(marker,'after')}>在此之后插入</button></div>}{marker&&onDelete&&<button type="button" className="sap-danger" disabled={submission.disabled} onClick={()=>submission.submit(onDelete)}>删除这个标记</button>}<Footer submission={submission}/></form></Sheet>;
}
export function StoryPlacementEditor({card,axis,busy=false,onSave,onUnplace,close}){
 const existing=card.time?.story?.axisVersion===1?card.time.story:null,[start,setStart]=useState(existing?.start??axis.anchor.coordinate),[lastDay,setLastDay]=useState(existing?existing.end-1:axis.anchor.coordinate),[spans,setSpans]=useState(!!existing&&existing.end-existing.start>1),[trackId,setTrack]=useState(existing?.trackId||axis.tracks[0]?.id),[row,setRow]=useState((existing?.row||0)+1),submission=useSubmission(busy,close);
 const changeStart=next=>{setStart(next);if(!spans)setLastDay(next);};
 return <Sheet title="故事时间位置" submission={submission}><form className="sap-form" onSubmit={e=>{e.preventDefault();void submission.submit(()=>{const end=spans?lastDay:start;if(start===''||end===''||!Number.isSafeInteger(Number(start))||!Number.isSafeInteger(Number(end))||Number(end)<Number(start))throw new Error('结束日期不能早于事件日期，请填写有效的整日日期。');if(!Number.isSafeInteger(Number(row))||Number(row)<1)throw new Error('层次须为大于零的整数。');return onSave({start:Number(start),end:Number(end)+1,trackId,row:Number(row)-1});});}}><p className="sap-intro"><strong>{card.title}</strong><br/>仅安排这张共享剧情卡的位置，不复制内容，不改动其他页面。</p><PositionFields axis={axis} coordinate={start} onChange={changeStart} label="事件日期"/><label className="sap-confirm"><input type="checkbox" checked={spans} onChange={e=>{setSpans(e.target.checked);if(e.target.checked&&(!Number.isSafeInteger(lastDay)||lastDay<start))setLastDay(start);}}/><span>跨越一段时间</span></label>{spans&&<PositionFields axis={axis} coordinate={lastDay} onChange={setLastDay} label="结束日期（包含当天）"/>}<label>故事轨道<select value={trackId} onChange={e=>setTrack(e.target.value)}>{axis.tracks.map(t=><option key={t.id} value={t.id}>{t.name}（{t.side==='below'?'轴下':'轴上'}）</option>)}</select></label><details className="sap-advanced"><summary>更多位置选项</summary><label>轨道内层次<input required type="number" min="1" step="1" value={row} onChange={e=>setRow(e.target.value)}/><small>第 1 层最靠近时间线；不会改变事件日期。</small></label></details>{existing&&onUnplace&&<button type="button" className="sap-danger" disabled={submission.disabled} onClick={()=>submission.submit(onUnplace)}>移回待安排 · 保留剧情卡</button>}<Footer submission={submission} label="保存位置"/></form></Sheet>;
}

export function StoryTrackEditor({track,axis,busy=false,onSave,onDelete,close}){
 const [name,setName]=useState(track?.name||''),[color,setColor]=useState(track?.color||'#7c8d73'),[side,setSide]=useState(track?.side||'above'),submission=useSubmission(busy,close);
 return <Sheet title={track?'故事轨道设置':'新建故事轨道'} submission={submission}><form className="sap-form" onSubmit={e=>{e.preventDefault();void submission.submit(()=>onSave({name:name.trim(),color,side}));}}><p className="sap-intro">线上、线下的意义由你决定。这里的轨道不影响叙述时间线。</p><label>轨道名称<input required autoFocus maxLength={80} value={name} onChange={e=>setName(e.target.value)}/></label><div className="sap-options" role="group" aria-label="轨道位置">{[['above','时间线上方'],['below','时间线下方']].map(([value,label])=><button type="button" key={value} aria-pressed={side===value} onClick={()=>setSide(value)}>{label}</button>)}</div><label className="sap-color">轨道颜色<input type="color" value={color} onChange={e=>setColor(e.target.value)}/></label>{track&&onDelete&&<button type="button" className="sap-danger" disabled={submission.disabled||axis.tracks.length<=1} onClick={()=>submission.submit(onDelete)}>删除轨道</button>}<Footer submission={submission}/></form></Sheet>;
}
